        String identifier = WizardStyle.fieldValue(identifierField, IDENTIFIER_PLACEHOLDER);

        if (password.equals(PLACEHOLDER_PASSWORD)) {
            password = "";
        }
        if (name.isBlank() || surname.isBlank() || email.isBlank()
                || password.isBlank() || identifier.isBlank()) {
            showError("Complete all fields");
            return;
        }

        try {
            LibraryFacade.getInstance().register(role, name, surname, email, password, identifier);
            JOptionPane.showMessageDialog(registrationPanel,
                    "Registration complete! You can now sign in.",
                    "Registration", JOptionPane.INFORMATION_MESSAGE);
            currentFrame.dispose();
            new Login().openLogin();
        } catch (RuntimeException ex) {
            showError(ex.getMessage());
        }
    }

