            validateLibrarian(name, surname, email, identifier);
        }

        if (userRegistry.institutionalEmailExists(email)) {
            throw new IllegalArgumentException("Email is already associated with an account.");
        }

        boolean identifierGiaUsato = student
                ? userRegistry.findStudentByStudentNumber(identifier) != null
                : userRegistry.findLibrarianByCode(identifier) != null;
        if (identifierGiaUsato) {
            throw new IllegalArgumentException("Identifier is already in use.");
        }

        // English implementation note.
        UserFactory factory = student ? new StudentFactory() : new LibrarianFactory();
        User newUser = factory.createUser(name, surname, email, password, identifier);

        boolean success = userRegistry.registerUser(newUser);
        if (!success){
            throw new RuntimeException("Server error: the user could not be saved. Please try again.");
        }
        return toDTO(newUser);
    }

    // ------------------------------------------------------------------ UC2
    /**
      * English implementation note.
      * English implementation note.
      * English implementation note.
      * English implementation note.
     */
    public UserDTO authenticate(String email, String password) {
        validateCredentialFormat(email, password);

        User user = userRegistry.findUserByEmail(email);

        if (user == null) {
            throw new SecurityException("Invalid credentials or user does not exist.");
        }
        if (user.isBloccato()) {
            throw new SecurityException("Account locked after too many failed attempts. Try again in "
                    + MINUTI_BLOCCO + " minutes.");
        }

        if (!verifyCredentials(user, password)) {
            incrementaTentativi(user);
            boolean appenaBloccato = user.getFailedAttempts() >= MAX_TENTATIVI;
            if (appenaBloccato) {
                bloccaAccountTemporaneamente(user, MINUTI_BLOCCO);
            }
            userRegistry.update(user);
            if (appenaBloccato) {
                throw new SecurityException("Invalid credentials. Account locked for " + MINUTI_BLOCCO
                        + " minutes after too many failed attempts.");
            }
            throw new SecurityException("Invalid credentials or user does not exist.");
        }

        resetTentativi(user);
        userRegistry.update(user);
        return toDTO(user);
    }

    /**
      * English implementation note.
      * English implementation note.
      * English implementation note.
     */
    private void validateCredentialFormat(String email, String password) {
        require(email != null && !email.isEmpty(), "Email is required.");
        require(isEmailWellFormed(email), "Invalid email format.");
        require(password != null && !password.isEmpty(), "Password is required.");
        require(password.length() >= 8, "Password must contain at least 8 characters.");
        require(password.length() <= 32, "Invalid password format.");
    }

    /** English implementation note. */
    private boolean isEmailWellFormed(String email) {
        return email.length() < 255 && email.matches(REGEX_EMAIL_ISTITUZIONALE);
    }

    // -------------------------------------------------------------- UC8 (profile)
    /**
      * English implementation note.
     */
    public UserDTO visualizzaProfilo(Long studentId) {
        Student student = userRegistry.findStudentById(studentId);
        if (student == null) {
            throw new IllegalArgumentException("Student not found");
        }
        return toDTO(student);
    }

    // ------------------------------------------------------------------ helper privati
    private boolean isValidRole(String role) {
        return "Student".equalsIgnoreCase(role) || "Librarian".equalsIgnoreCase(role);
    }

    private void validateStudent(String name, String surname, String email, String studentNumber) {
        validateNameAndSurname(name, surname);
        validateEmail(email);
        validateIdentifier(studentNumber, "studentNumber");
        if (!studentNumber.matches(REGEX_STUDENT_NUMBER)) {
            throw new IllegalArgumentException(
                    "Unrecognized identifier format: the student ID must be an uppercase letter followed by 8 digits (e.g. N86001234).");
        }
    }

    private void validateLibrarian(String name, String surname, String email, String code) {
        validateNameAndSurname(name, surname);
        validateEmail(email);
        validateIdentifier(code, "code identifier");
    }

    private void validateNameAndSurname(String name, String surname) {
        if (!name.matches("\\p{L}{1,20}")) {
            throw new IllegalArgumentException("Invalid first-name format (letters only, max 20 characters).");
        }
        if (surname == null || surname.isEmpty()) {
            throw new IllegalArgumentException("Last name is required.");
        }
        if (!surname.matches("\\p{L}{1,20}")) {
            throw new IllegalArgumentException("Invalid last-name format (letters only, max 20 characters).");
        }
    }

    private void validateEmail(String email) {
        if (email == null || email.isEmpty()) {
            throw new IllegalArgumentException("Email is required.");
        }
        // English implementation note.
        if (email.length() >= 255) {
            throw new IllegalArgumentException("Email is too long (max 255 characters).");
        }
        if (!isEmailWellFormed(email)) {
            throw new IllegalArgumentException("Invalid email format.");
        }
    }

    private void validateIdentifier(String identifier, String label) {
        if (identifier == null || identifier.isEmpty()) {
            throw new IllegalArgumentException("Identifier is required.");
        }
        if (!identifier.matches("[A-Za-z0-9]+")) {
            throw new IllegalArgumentException("Invalid " + label + " format.");
        }
    }

    private boolean verifyCredentials(User user, String password) {
        return password != null && password.equals(user.getPassword());
    }

    private void incrementaTentativi(User user) {
        user.setFailedAttempts(user.getFailedAttempts() + 1);
    }

    private void bloccaAccountTemporaneamente(User user, int durataMinuti) {
        user.setLockedUntilA(LocalDateTime.now(ZoneId.of("Europe/Rome")).plusMinutes(durataMinuti));
        user.setFailedAttempts(0);
    }

    private void resetTentativi(User user) {
        user.setFailedAttempts(0);
        user.setLockedUntilA(null);
    }

    /** English implementation note. */
    private UserDTO toDTO(User user) {
        UserDTO dto = new UserDTO();
        dto.setId(user.getId());
        dto.setName(user.getName());
        dto.setSurname(user.getSurname());
        dto.setInstitutionalEmail(user.getInstitutionalEmail());
        if (user instanceof Student s) {
            dto.setRole("Student");
            dto.setIdentifier(s.getStudentNumber());
            dto.setTotalVisitCount(s.getTotalVisitCount());
        } else if (user instanceof Librarian b) {
            dto.setRole("Librarian");
            dto.setIdentifier(b.getInternalIdentifierCode());
        }
        return dto;
    }
}
